// Generated by toolbox — Reanimated-native animations.
// Do not edit by hand: change the SkSL Shader node and export again.
//
// Native mode (toolbox export option animation: "native"): every animated
// value is its own shared value, driven by withSequence / withDelay /
// withTiming / withSpring, so app code can interrupt it, chain from it or
// hand it to a gesture (cancelAnimation, withSpring to a new target). Easings
// are Reanimated's own where they equal toolbox's and toolbox's formula
// otherwise (manifest.json native.values lists which).
//
// Reanimated starts each withSequence step on the frame its predecessor
// finished, and a withTiming finishes on the first frame at or past its
// duration. On a steady display clock every step still lands on its toolbox
// frame (durations end 1 µs early to absorb float noise); a frame whose
// timestamp arrives early by more than that pushes the rest of that value's
// sequence one frame late, and the lag adds up step by step. Export with
// animation "worklet" for frame-exact playback whatever the clock does.

import { useCallback, useEffect, useMemo } from "react";
import {
  cancelAnimation,
  Easing,
  useDerivedValue,
  useSharedValue,
  withDelay,
  withSequence,
  withTiming,
  type SharedValue,
  type DerivedValue,
} from "react-native-reanimated";
import { scheduleOnUI } from "react-native-worklets";
import { SEGMENTS, type SegmentName } from "./toolbox-clock";
import { easeOf, evaluateTrackRaw, type TimelineTrack } from "./toolbox-timeline";
import { colorAt, looped, segmentEase } from "./toolbox-native";

export const NAME = "Aurora";
export const TIMELINE = {
  fps: 60,
  ticksPerFrame: 1000,
  durationTicks: 300000,
  durationSec: 5,
} as const;

export const CANVAS = { width: 512, height: 512 } as const;

// The timeline in ms (TIMELINE.durationSec) — looped animations pad to it.
const TIMELINE_MS = 5000;

// Toolbox frames → ms, 1 µs short. Reanimated ends a step on the first
// frame at or past its duration, and the frame that lands ON a key must
// count: without the margin, float noise in (frame time − start time)
// pushes about half the boundaries to the next frame, a lag that adds up
// down a withSequence.
function frames(n: number): number {
  "worklet";
  return (n * 1000) / TIMELINE.fps - 0.001;
}

// The same curves as data: evaluateTrack(TRACKS.<key>, tick) from
// ./toolbox-timeline is the frame-exact (worklet-mode) value.
export const TRACKS: Record<string, TimelineTrack> = {
  // scale: Animated Value scale (3 keys)
  scale: {"kind":"scalar","keys":[{"tick":0,"value":3,"easing":"easeOutBack"},{"tick":120000,"value":4.2,"easing":"easeInOutCubic"},{"tick":300000,"value":3,"easing":"linear"}]},
  // drift_x: Animated Value drift (2 keys)
  drift_x: {"kind":"scalar","keys":[{"tick":0,"value":0,"easing":"linear"},{"tick":300000,"value":1.5,"easing":"linear"}]},
  // contrast: Animated Value contrast (4 keys)
  contrast: {"kind":"scalar","keys":[{"tick":0,"value":0.8,"easing":"easeOutElastic"},{"tick":90000,"value":1.6,"easing":"easeInOutSine"},{"tick":240000,"value":1.2,"easing":"hold"},{"tick":300000,"value":1.2,"easing":"linear"}]},
  // c2: Color glow.color (3 keys, oklab)
  c2: {"kind":"color","colorSpace":"oklab","quantize8":true,"alpha":1,"keys":[{"tick":0,"value":[1,0.47843137254901963,0.27058823529411763,1],"easing":"easeInOutQuad"},{"tick":150000,"value":[1,0.23921568627450981,0.5450980392156862,1],"easing":"easeInOutQuad"},{"tick":300000,"value":[1,0.47843137254901963,0.27058823529411763,1],"easing":"linear"}]},
};

// ---- easings Reanimated has no equal for: toolbox-timeline.ts's own math ----

// easeOutElastic: Easing.elastic(b) is a different curve (1 − cos³(tπ/2)·cos(tbπ)).
const tbxEaseOutElastic = (t: number) => {
  "worklet";
  return easeOf("easeOutElastic", t);
};

// drift_x: toolbox's linear cut to f0–f120, as the fraction of the move 0 → 0.6000000000000001.
const tbxCut0 = (t: number) => {
  "worklet";
  return ((evaluateTrackRaw(TRACKS.drift_x, 0 + t * 120000) as number) - 0) / 0.6000000000000001;
};

// contrast: toolbox's easeInOutSine cut to f90–f120, as the fraction of the move 1.6 → 1.5618033988749895.
const tbxCut1 = (t: number) => {
  "worklet";
  return ((evaluateTrackRaw(TRACKS.contrast, 90000 + t * 30000) as number) - 1.6) / -0.038196601125010554;
};

// c2: toolbox's easeInOutQuad cut to f0–f120, as the fraction of the move 0 → 0.92.
const tbxCut2 = (t: number) => {
  "worklet";
  return (segmentEase(TRACKS.c2.keys[0], 0 + t * 0.8) - 0) / 0.92;
};

// drift_x: toolbox's linear cut to f120–f300, as the fraction of the move 0.6000000000000001 → 1.5.
const tbxCut3 = (t: number) => {
  "worklet";
  return ((evaluateTrackRaw(TRACKS.drift_x, 120000 + t * 180000) as number) - 0.6000000000000001) / 0.8999999999999999;
};

// contrast: toolbox's easeInOutSine cut to f120–f240, as the fraction of the move 1.5618033988749895 → 1.2.
const tbxCut4 = (t: number) => {
  "worklet";
  return ((evaluateTrackRaw(TRACKS.contrast, 120000 + t * 120000) as number) - 1.5618033988749895) / -0.3618033988749896;
};

// c2: toolbox's easeInOutQuad cut to f120–f150, as the fraction of the move 0.92 → 1.
const tbxCut5 = (t: number) => {
  "worklet";
  return (segmentEase(TRACKS.c2.keys[0], 0.8 + t * 0.19999999999999996) - 0.92) / 0.07999999999999996;
};

// scale: toolbox's easeInOutCubic cut to f150–f180, as the fraction of the move 4.177777777777778 → 4.022222222222222.
const tbxCut6 = (t: number) => {
  "worklet";
  return ((evaluateTrackRaw(TRACKS.scale, 150000 + t * 30000) as number) - 4.177777777777778) / -0.1555555555555559;
};

// drift_x: toolbox's linear cut to f150–f180, as the fraction of the move 0.75 → 0.8999999999999999.
const tbxCut7 = (t: number) => {
  "worklet";
  return ((evaluateTrackRaw(TRACKS.drift_x, 150000 + t * 30000) as number) - 0.75) / 0.1499999999999999;
};

// contrast: toolbox's easeInOutSine cut to f150–f180, as the fraction of the move 1.4618033988749894 → 1.3381966011250106.
const tbxCut8 = (t: number) => {
  "worklet";
  return ((evaluateTrackRaw(TRACKS.contrast, 150000 + t * 30000) as number) - 1.4618033988749894) / -0.12360679774997885;
};

// c2: toolbox's easeInOutQuad cut to f150–f180, as the fraction of the move 0 → 0.08000000000000002.
const tbxCut9 = (t: number) => {
  "worklet";
  return (segmentEase(TRACKS.c2.keys[1], 0 + t * 0.2) - 0) / 0.08000000000000002;
};

// ---- one animation per value ----

// scale: Animated Value scale (3 keys) — starts at 3.
export function scaleAnimation(loop = false) {
  "worklet";
  return looped(
    withSequence(
      // f0 → f120 easeOutBack (equal to the last ulp)
      withTiming(4.2, { duration: frames(120), easing: Easing.out(Easing.back(1.70158)) }),
      // f120 → f300 easeInOutCubic (equal to the last ulp)
      withTiming(3, { duration: frames(180), easing: Easing.inOut(Easing.cubic) })
    ),
    5000,
    TIMELINE_MS,
    3,
    loop
  );
}

// scale over one segment (SEGMENTS), from the segment's start.
export function scaleSegmentAnimation(segment: SegmentName, loop = false): number {
  "worklet";
  switch (segment) {
    case "intro": // f0–f120
      return looped(
        // f0 → f120 easeOutBack (equal to the last ulp)
        withTiming(4.2, { duration: frames(120), easing: Easing.out(Easing.back(1.70158)) }),
        2000,
        2000,
        3,
        loop
      );
    case "loop": // f120–f300
      return looped(
        // f120 → f300 easeInOutCubic (equal to the last ulp)
        withTiming(3, { duration: frames(180), easing: Easing.inOut(Easing.cubic) }),
        3000,
        3000,
        4.2,
        loop
      );
    case "flash": // f150–f180
      return looped(
        // f120 → f300 easeInOutCubic, cut to f150–f180 (toolbox's curve)
        withTiming(4.022222222222222, { duration: frames(30), easing: tbxCut6 }),
        500,
        500,
        4.177777777777778,
        loop
      );
  }
  return scaleAnimation(loop);
}

// drift_x: Animated Value drift (2 keys) — starts at 0.
export function drift_xAnimation(loop = false) {
  "worklet";
  return looped(
    // f0 → f300 linear
    withTiming(1.5, { duration: frames(300), easing: Easing.linear }),
    5000,
    TIMELINE_MS,
    0,
    loop
  );
}

// drift_x over one segment (SEGMENTS), from the segment's start.
export function drift_xSegmentAnimation(segment: SegmentName, loop = false): number {
  "worklet";
  switch (segment) {
    case "intro": // f0–f120
      return looped(
        // f0 → f300 linear, cut to f0–f120 (toolbox's curve)
        withTiming(0.6000000000000001, { duration: frames(120), easing: tbxCut0 }),
        2000,
        2000,
        0,
        loop
      );
    case "loop": // f120–f300
      return looped(
        // f0 → f300 linear, cut to f120–f300 (toolbox's curve)
        withTiming(1.5, { duration: frames(180), easing: tbxCut3 }),
        3000,
        3000,
        0.6000000000000001,
        loop
      );
    case "flash": // f150–f180
      return looped(
        // f0 → f300 linear, cut to f150–f180 (toolbox's curve)
        withTiming(0.8999999999999999, { duration: frames(30), easing: tbxCut7 }),
        500,
        500,
        0.75,
        loop
      );
  }
  return drift_xAnimation(loop);
}

// contrast: Animated Value contrast (4 keys) — starts at 0.8.
export function contrastAnimation(loop = false) {
  "worklet";
  return looped(
    withSequence(
      // f0 → f90 easeOutElastic (toolbox's curve)
      withTiming(1.6, { duration: frames(90), easing: tbxEaseOutElastic }),
      // f90 → f240 easeInOutSine (equal to the last ulp)
      withTiming(1.2, { duration: frames(150), easing: Easing.inOut(Easing.sin) }),
      // f240 → f300 hold
      withDelay(frames(60), withTiming(1.2, { duration: 0 }))
    ),
    5000,
    TIMELINE_MS,
    0.8,
    loop
  );
}

// contrast over one segment (SEGMENTS), from the segment's start.
export function contrastSegmentAnimation(segment: SegmentName, loop = false): number {
  "worklet";
  switch (segment) {
    case "intro": // f0–f120
      return looped(
        withSequence(
          // f0 → f90 easeOutElastic (toolbox's curve)
          withTiming(1.6, { duration: frames(90), easing: tbxEaseOutElastic }),
          // f90 → f240 easeInOutSine, cut to f90–f120 (toolbox's curve)
          withTiming(1.5618033988749895, { duration: frames(30), easing: tbxCut1 })
        ),
        2000,
        2000,
        0.8,
        loop
      );
    case "loop": // f120–f300
      return looped(
        withSequence(
          // f90 → f240 easeInOutSine, cut to f120–f240 (toolbox's curve)
          withTiming(1.2, { duration: frames(120), easing: tbxCut4 }),
          // f240 → f300 hold
          withDelay(frames(60), withTiming(1.2, { duration: 0 }))
        ),
        3000,
        3000,
        1.5618033988749895,
        loop
      );
    case "flash": // f150–f180
      return looped(
        // f90 → f240 easeInOutSine, cut to f150–f180 (toolbox's curve)
        withTiming(1.3381966011250106, { duration: frames(30), easing: tbxCut8 }),
        500,
        500,
        1.4618033988749894,
        loop
      );
  }
  return contrastAnimation(loop);
}

// c2: Color glow.color (3 keys, oklab): a 0..1 progress per segment; colorAt mixes the keys in OKLab and snaps to 8 bits.
export function c2Progress0Animation(loop = false) {
  "worklet";
  // f0 → f150 easeInOutQuad
  return looped(withTiming(1, { duration: frames(150), easing: Easing.inOut(Easing.quad) }), 2500, TIMELINE_MS, 0, loop);
}
export function c2Progress1Animation(loop = false) {
  "worklet";
  // f150 → f300 easeInOutQuad
  return looped(withDelay(frames(150), withTiming(1, { duration: frames(150), easing: Easing.inOut(Easing.quad) })), 5000, TIMELINE_MS, 0, loop);
}
export function c2Progress0SegmentAnimation(segment: SegmentName, loop = false): number {
  "worklet";
  switch (segment) {
    case "intro": // f0–f120
      // f0 → f150 easeInOutQuad, cut to f0–f120 (toolbox's curve)
      return looped(withTiming(0.92, { duration: frames(120), easing: tbxCut2 }), 2000, 2000, 0, loop);
    case "loop": // f120–f300
      // f0 → f150 easeInOutQuad, cut to f120–f150 (toolbox's curve)
      return looped(withTiming(1, { duration: frames(30), easing: tbxCut5 }), 500, 3000, 0.92, loop);
    case "flash": // f150–f180
      return 1; // no move here
  }
  return 0;
}
export function c2Progress1SegmentAnimation(segment: SegmentName, loop = false): number {
  "worklet";
  switch (segment) {
    case "intro": // f0–f120
      return 0; // no move here
    case "loop": // f120–f300
      // f150 → f300 easeInOutQuad
      return looped(withDelay(frames(30), withTiming(1, { duration: frames(150), easing: Easing.inOut(Easing.quad) })), 3000, 3000, 0, loop);
    case "flash": // f150–f180
      // f150 → f300 easeInOutQuad, cut to f150–f180 (toolbox's curve)
      return looped(withTiming(0.08000000000000002, { duration: frames(30), easing: tbxCut9 }), 500, 500, 0, loop);
  }
  return 0;
}

// ---- segments ----

// Each value at each segment's start (colors: every segment's progress) —
// where playSegment() puts it before the segment plays.
export interface SegmentStart {
  scale: number;
  drift_x: number;
  contrast: number;
  c2: number[];
}
export const SEGMENT_STARTS: Record<SegmentName, SegmentStart> = {
  "intro": { scale: 3, drift_x: 0, contrast: 0.8, c2: [0, 0] },
  "loop": { scale: 4.2, drift_x: 0.6000000000000001, contrast: 1.5618033988749895, c2: [0.92, 0] },
  "flash": { scale: 4.177777777777778, drift_x: 0.75, contrast: 1.4618033988749894, c2: [1, 0] },
};

// ---- the hook ----

export interface ToolboxAnimationValues {
  // scale: Animated Value scale (3 keys)
  scale: SharedValue<number>;
  // drift_x: Animated Value drift (2 keys)
  drift_x: SharedValue<number>;
  // contrast: Animated Value contrast (4 keys)
  contrast: SharedValue<number>;
  // c2: Color glow.color (3 keys, oklab) — [r, g, b, a], 0..1
  c2: DerivedValue<number[]>;
}

export interface PlaySegmentOptions {
  // Repeat the segment until stop() / another play.
  loop?: boolean;
  // "start" (default): every value jumps to its value at the segment's start
  // first — the frames toolbox shows. "current": scalar values animate on
  // from where they are (an interruption); colors still start at the
  // segment's start.
  from?: "start" | "current";
}

export interface ToolboxAnimations {
  values: ToolboxAnimationValues;
  // (Re)start every value from the first frame, all on one UI frame. loop:
  // repeat the timeline (TIMELINE.durationSec) until stop().
  play(opts?: { loop?: boolean }): void;
  // Play one named segment (toolbox-clock.ts SEGMENTS) the same way; false
  // for a name SEGMENTS doesn't have.
  playSegment(segment: SegmentName, opts?: PlaySegmentOptions): boolean;
  // Cancel every animation where it is (each value keeps its state).
  stop(): void;
}

// The shared values the component reads. autoplay (default true) plays
// on mount; pass false to call play() / playSegment() yourself, or drive
// any value directly.
export function useToolboxAnimations(opts: { autoplay?: boolean; loop?: boolean } = {}): ToolboxAnimations {
  const { autoplay = true, loop = false } = opts;
  const scaleValue = useSharedValue(3);
  const drift_xValue = useSharedValue(0);
  const contrastValue = useSharedValue(0.8);
  const c2Progress0 = useSharedValue(0);
  const c2Progress1 = useSharedValue(0);
  const c2Value = useDerivedValue(() => colorAt(TRACKS.c2, [c2Progress0.value, c2Progress1.value]));
  const play = useCallback(
    (o: { loop?: boolean } = {}) => {
      const repeat = o.loop ?? loop;
      scheduleOnUI(() => {
        "worklet";
        // Start inside a frame callback: there an animation's start time is
        // the frame's own timestamp, so every step lands on display frames
        // (outside one it is "now", somewhere between two frames).
        requestAnimationFrame(() => {
          scaleValue.value = 3;
          scaleValue.value = scaleAnimation(repeat);
          drift_xValue.value = 0;
          drift_xValue.value = drift_xAnimation(repeat);
          contrastValue.value = 0.8;
          contrastValue.value = contrastAnimation(repeat);
          c2Progress0.value = 0;
          c2Progress0.value = c2Progress0Animation(repeat);
          c2Progress1.value = 0;
          c2Progress1.value = c2Progress1Animation(repeat);
        });
      });
    },
    [loop, scaleValue, drift_xValue, contrastValue, c2Progress0, c2Progress1]
  );
  const playSegment = useCallback(
    (segment: SegmentName, o: PlaySegmentOptions = {}) => {
      if (!Object.prototype.hasOwnProperty.call(SEGMENTS, segment)) return false;
      const repeat = o.loop ?? false;
      const jump = (o.from ?? "start") === "start";
      scheduleOnUI(() => {
        "worklet";
        const s = SEGMENT_STARTS[segment];
        // Start inside a frame callback: there an animation's start time is
        // the frame's own timestamp, so every step lands on display frames
        // (outside one it is "now", somewhere between two frames).
        requestAnimationFrame(() => {
          if (jump) scaleValue.value = s.scale;
          scaleValue.value = scaleSegmentAnimation(segment, repeat);
          if (jump) drift_xValue.value = s.drift_x;
          drift_xValue.value = drift_xSegmentAnimation(segment, repeat);
          if (jump) contrastValue.value = s.contrast;
          contrastValue.value = contrastSegmentAnimation(segment, repeat);
          c2Progress0.value = s.c2[0];
          c2Progress0.value = c2Progress0SegmentAnimation(segment, repeat);
          c2Progress1.value = s.c2[1];
          c2Progress1.value = c2Progress1SegmentAnimation(segment, repeat);
        });
      });
      return true;
    },
    [scaleValue, drift_xValue, contrastValue, c2Progress0, c2Progress1]
  );
  const stop = useCallback(() => {
    cancelAnimation(scaleValue);
    cancelAnimation(drift_xValue);
    cancelAnimation(contrastValue);
    cancelAnimation(c2Progress0);
    cancelAnimation(c2Progress1);
  }, [scaleValue, drift_xValue, contrastValue, c2Progress0, c2Progress1]);
  useEffect(() => {
    if (autoplay) play();
    return stop;
  }, [autoplay, play, stop]);
  return useMemo(
    () => ({ values: { scale: scaleValue, drift_x: drift_xValue, contrast: contrastValue, c2: c2Value }, play, playSegment, stop }),
    [play, playSegment, stop, scaleValue, drift_xValue, contrastValue, c2Value]
  );
}
